pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(0x1234);
        address newOwner = address(0x5678);

        // Set owner to a known address
        vm.prank(c.owner()); // deployer is initial owner
        c.transferOwnership(owner);

        // Act as owner: call owned()
        vm.prank(owner);
        c.owned();

        // Transfer ownership from owner to newOwner
        vm.prank(owner);
        c.transferOwnership(newOwner);

        // Now try to call owned() as the original owner (who is no longer owner)
        // In reference: reverts; in buggy: succeeds
        bool ok;
        vm.prank(owner);
        try c.owned() { ok = true; } catch { ok = false; }

        assertTrue(ok); // Reference: false, Bug: true
    }
}

