pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address newOwner = address(0x5678);

        // Non-owner calls owned()
        vm.prank(nonOwner);
        bool revertHappened;
        try c.owned() {
            revertHappened = false;
        } catch {
            revertHappened = true;
        }

        if (!revertHappened) {
            // In buggy version, non-owner can now transfer ownership
            vm.prank(nonOwner);
            c.transferOwnership(newOwner);
        }

        // Assert: in reference, owner is still original (address(this)), in buggy it is newOwner
        assertTrue(c.owner() == address(this));
    }
}

