pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: owner() is initially address(0) since we didn't set it
        // We'll make the contract own itself by transferring to address(this) first
        vm.prank(address(0)); // The deployer? Actually owner starts as address(0), which is the deployer? No — owner is uninitialized, so address(0) passes onlyOwner check? No, msg.sender would be address(0) if we prank it.
        c.transferOwnership(address(this));

        // Now owner is address(this)
        vm.prank(address(this));
        c.owned();

        // Transfer to a new owner
        address newOwner = address(0x1234);
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Now call owned() as the original owner (address(this)) — should revert in reference
        vm.prank(address(this));
        // We'll check if it reverts or not by wrapping in try/catch
        bool didRevert;
        try c.owned() {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        // In reference, it reverts (didRevert == true); in buggy version, it does not revert (didRevert == false)
        // After that, check final owner value
        // In reference: owner is still newOwner (0x1234)
        // In buggy: original owner call succeeded and owner became address(this) again (since owned() does nothing but transferOwnership is not called yet)
        // Actually the buggy owned() does nothing, so owner remains newOwner. Hmm, need a different approach.
        // Let's instead: after the non-reverting call in buggy, we can have the original owner call transferOwnership back to themselves.
        // Simpler: after the non-owner call to owned() succeeds (buggy), the original owner can transfer ownership to themselves, changing owner.
        // In reference, the non-owner call reverts, so they can't transfer.
        // Let's do this:
        // 1. Set owner to address(this)
        // 2. Prank as non-owner (address(0xdead)) and call owned() — reference reverts, buggy doesn't
        // 3. Then prank as that non-owner and call transferOwnership(address(0xdead))
        // In reference, step 2 reverts so owner unchanged (still address(this)); step 3 also reverts because onlyOwner fails
        // In buggy, step 2 succeeds (does nothing), step 3 succeeds because onlyOwner passes (but owner is still address(this)), so owner becomes address(0xdead)
        // So final owner differs.
        // But we need to not use try/catch on transferOwnership because we want to assert on final owner.
        // Let's use the try/catch on owned() to detect revert vs success, then check owner after.
        // Reset
        c = new C(); // Fresh deploy
        vm.prank(address(0));
        c.transferOwnership(address(this));

        address nonOwner = address(0xdead);
        vm.prank(nonOwner);
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Now prank as nonOwner and try to transfer ownership
        vm.prank(nonOwner);
        c.transferOwnership(nonOwner); // In reference this reverts, but we don't catch it — we just check final owner

        // In reference: owned() reverted, so transferOwnership also reverts (since onlyOwner fails), owner stays address(this)
        // In buggy: owned() succeeded (did nothing), then transferOwnership succeeds (since onlyOwner passes — but owner is still address(this)! Actually onlyOwner checks msg.sender == owner, and owner is address(this), so it will revert! That's a problem — need different scenario.)
        // Let's think again.
        // Simpler: call owned() as non-owner, then call owned() as owner — but that doesn't change owner.
        // The difference must ultimately change owner.
        // Alternative: After non-owner calls owned() and it doesn't revert (buggy), the non-owner can call transferOwnership to themselves — but onlyOwner will fail because owner is still address(this), so they can't.
        // So need a different call sequence.
        // The known correct approach: Call owned() as owner, then transfer to new owner, then call owned() as original owner. In reference, second owned() reverts (original not owner). In buggy, it succeeds. Then the original owner can transferOwnership back to themselves, changing owner.
        // Let's implement that.
        // Fresh deploy
        c = new C();
        vm.prank(address(0));
        c.transferOwnership(address(this));

        address originalOwner = address(this);
        address newOwner = address(0x1234);

        // Step 1: call owned() as owner
        vm.prank(originalOwner);
        c.owned();

        // Step 2: transfer to newOwner
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);

        // Step 3: call owned() as originalOwner — reference reverts, buggy succeeds
        vm.prank(originalOwner);
        bool reverted3;
        try c.owned() {
            reverted3 = false;
        } catch {
            reverted3 = true;
        }

        // Step 4: originalOwner tries to transfer ownership back to themselves — only works if owned() succeeded (buggy)
        vm.prank(originalOwner);
        c.transferOwnership(originalOwner); // In reference, this reverts; in buggy, it succeeds

        // Now check final owner
        address finalOwner = c.owner();
        // In reference: finalOwner == newOwner (0x1234) because transferOwnership in step 4 reverted
        // In buggy: finalOwner == originalOwner because step 3 succeeded, so step 4 succeeded
        bool pass = (finalOwner == newOwner); // reference passes this assert? Actually reference: owner is newOwner, so pass == true (if newOwner != originalOwner)
        bool fail = (finalOwner == originalOwner); // buggy: owner is originalOwner, so pass == false
        // We want assertTrue that passes for reference but fails for buggy
        // So assert true that owner == newOwner
        assertTrue(finalOwner == newOwner, "Owner should be newOwner in reference");
    }
}

