pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initially owner = address(this) (deployer = address(this) in test)
        // Let an unauthorized user (address(1)) transfer ownership to address(2)
        // In the bug, this succeeds; in reference, it reverts due to onlyOwner
        vm.prank(address(1));
        c.transferOwnership(address(2));
        // Now call owned() - in reference, owner is still deployer, so owned() reverts because msg.sender != owner
        // In bug, owner is address(2), so owned() reverts because msg.sender != owner (still address(1) from prank? Actually after transferOwnership, msg.sender is address(1) which is not the new owner address(2), so also revert? Wait we must set up a scenario where only one reverts.)
        // Let's clarify: in reference, transferOwnership from address(1) reverts, so owner stays as deployer. In bug, owner becomes address(2).
        // Now call owned() from address(1) (the unauthorized caller). In both cases, msg.sender != owner, so both revert. That doesn't show divergence.
        // We need a scenario where one call succeeds and the other reverts.
        // We'll have the deployer initially, then have an unauthorized user call transferOwnership(address(1)). In reference, revert; in bug, owner becomes address(1) (the caller). Then from address(1) call owned(). In reference, owner is deployer, so revert; in bug, owner is address(1), so success.
        vm.prank(address(1));
        c.transferOwnership(address(1));
        // Now call owned() from address(1)
        vm.prank(address(1));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(ok, "owned() should revert in reference but succeed in bug");
    }
}

